// MEMORY-GATES MG6 (mini-estcal, 2026-11-17): the offline estimate against the phone peak the phone-tier probe measured
// for each pinned product (MG11). A model change that under-predicts any zone fails here. The rows are regenerated by
// `memory-calibration.golden-gen.mjs` from the real products whenever the model changes, which bumps MEMORY_EPOCH.
import { expect, test } from 'vitest'

import { bootPhoneBytes, RENDERER_FLOOR_BYTES } from './boot-memory-cost.ts'
import golden from './memory-calibration.golden.json' with { type: 'json' }
import { MEMORY_EPOCH } from './memory-epoch.ts'

type Zone = Readonly<(typeof golden.zones)[number]>

const MB = 1_000_000
/** The readings are one-run noisy (Brasscap read 462 and 360 MB of renderer on two runs; Ink Cel and Pastel, near-identical
 *  products, 737 and 805 MB). Brasscap at 925 MB and the Open Plots top at 796 MB carry the same terms, so no conservative
 *  model is within 16% of both. The ceiling keeps a model from buying safety with a blanket margin. */
const CEILING = 1.3
const ZONES = 10
const LINE = 1.5e9
/** MG11's ten zones: Showcase ships Ink Cel and Pastel, and Open Plots its 17 plots. */
const SHOWCASE = new Set(['ink-cel-valley', 'pastel-plain'])

function zoneOf(zone: Zone): string {
  if (zone.slug.startsWith('open-plot-')) {
    return 'open-plots'
  }
  return SHOWCASE.has(zone.slug) ? 'showcase' : zone.slug
}

/** The stored resident estimate under the boot floor the current constants give. */
function estimate(zone: Zone): number {
  return Math.max(
    zone.residentLoading,
    bootPhoneBytes({
      renderer: RENDERER_FLOOR_BYTES + zone.rendererContent,
      runtimeReading: zone.runtimeReading,
    }),
  )
}

test('MG6: the paired table was generated by the current memory model', (): void => {
  expect(
    golden.epoch,
    'regenerate memory-calibration.golden.json after a model change',
  ).toBe(MEMORY_EPOCH)
  expect(new Set(golden.zones.map(zoneOf)).size).toBe(ZONES)
})

test('MG6: no zone is estimated under its measured phone peak, nor far over it', (): void => {
  for (const zone of golden.zones) {
    const bytes = estimate(zone)
    const measured = zone.measuredMB * MB
    expect(bytes, zone.slug).toBe(zone.loading)
    expect(
      bytes,
      `${zone.slug} under its measured phone peak`,
    ).toBeGreaterThanOrEqual(measured)
    expect(
      bytes / measured,
      `${zone.slug} over its measured peak`,
    ).toBeLessThanOrEqual(CEILING)
  }
})

test('MG6: the two zones the epoch-2 estimate let under the 1.5 GB line are over it now', (): void => {
  const over = golden.zones
    .filter((zone: Zone): boolean => zone.loading > LINE)
    .map((zone: Zone): string => zone.slug)
  expect(over).toEqual(
    expect.arrayContaining(['nalati-grasslands', 'driftwood-isle']),
  )
})
